-- REAL CCRS crash data (data.ca.gov) + population/coords (california-cities-full.csv).
-- 2019=partial, 2026=prov. Rates derive at render from population.

create table if not exists city_year (city text, county text, year int, status text, population int,
 lat real, lng real, elevation_ft int,
 fatal_crashes int, injury_crashes int, fatalities int, injuries int, serious_injuries int,
 occupant_f int, occupant_i int, ped_f int, ped_i int, bike_f int, bike_i int, moto_f int, moto_i int,
 older_f int, older_i int, unrestrained_f int, unrestrained_i int, alcohol_f int, alcohol_i int,
 drug_f int, drug_i int, distracted_f int, distracted_i int, speeding_f int, speeding_i int,
 primary key(city,year));
create table if not exists county_year(county text,year int,population bigint,injuries int,fatalities int,primary key(county,year));
create table if not exists state_year(state text,year int,population bigint,injuries int,fatalities int,primary key(state,year));
create table if not exists city_top_roads(city text,rank int,road text,crashes int,injuries int,fatalities int,primary key(city,rank));
create table if not exists city_top_intersections(city text,rank int,intersection text,crashes int,injuries int,fatalities int,primary key(city,rank));
create table if not exists city_time_profile(city text,dim text,bucket int,crashes int,primary key(city,dim,bucket));






